import{_ as d,o as a,c as r,a2 as h}from"./chunks/framework.CqpfiAoK.js";const Z=JSON.parse('{"title":"Реестр Десяти Тысяч Рас","description":"","frontmatter":{},"headers":[],"relativePath":"ru/94-万族名录.md","filePath":"ru/94-万族名录.md","lastUpdated":1789183869000}'),e={name:"ru/94-万族名录.md"};function n(i,t,l,o,b,s){return a(),r("div",null,[...t[0]||(t[0]=[h('<h1 id="реестр-десяти-тысяч-рас" tabindex="-1">Реестр Десяти Тысяч Рас <a class="header-anchor" href="#реестр-десяти-тысяч-рас" aria-label="Permalink to &quot;Реестр Десяти Тысяч Рас&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>Номер документа</td><td>94</td></tr><tr><td>Модуль</td><td>Приложения и справочные материалы</td></tr><tr><td>Ключевые слова</td><td>реестр десяти тысяч рас, классификация рас, разумные расы, черты рас, Республика Десяти Тысяч Рас</td></tr></tbody></table><h2 id="i-пояснения-к-реестру" tabindex="-1">I. Пояснения к реестру <a class="header-anchor" href="#i-пояснения-к-реестру" aria-label="Permalink to &quot;I. Пояснения к реестру&quot;">​</a></h2><p>Настоящий реестр охватывает известные основные разумные расы в рамках Симбиотической Цивилизации Якоря (Республики Десяти Тысяч Рас), сгруппированные по формам жизни и путям эволюции. Для каждой расы указаны название, форма жизни, ключевые черты, культурные особенности и место в симбиотической цивилизации. Настоящий реестр является динамически обновляемым документом: по мере углубления межплоскостных исследований в него будут постоянно добавляться вновь открытые расы. Основной принцип Республики Десяти Тысяч Рас таков: все разумные расы, независимо от формы и уровня культивации, равны перед законом и пользуются всеми правами, предоставленными симбиотической цивилизацией.</p><h2 id="ii-обзор-классификации-рас" tabindex="-1">II. Обзор классификации рас <a class="header-anchor" href="#ii-обзор-классификации-рас" aria-label="Permalink to &quot;II. Обзор классификации рас&quot;">​</a></h2><p>Разумные расы Вселенной Хэнъюань по основным характеристикам форм жизни делятся на следующие восемь крупных категорий:</p><table tabindex="0"><thead><tr><th>Категория</th><th>Характеристики формы жизни</th><th>Известное число рас (ок.)</th><th>Представительные расы</th></tr></thead><tbody><tr><td>Гуманоидная форма</td><td>Обладают гуманоидным строением тела, прямоходящие, с высокоразвитым мозгом</td><td>ок. 3000</td><td>Rén Zú (Человеческая Раса), Jīnglíng Zú (Раса Эльфов), Ǎirén Zú (Раса Дварфов)</td></tr><tr><td>Звериная форма</td><td>Обладают животными чертами тела, могут иметь или не иметь способность к перевоплощению</td><td>ок. 5000</td><td>Lóng Zú (Раса Драконов), Fènghuáng Zú (Раса Фениксов), Lángrén Zú (Раса Оборотней)</td></tr><tr><td>Растительная форма</td><td>Принимают растения как основную форму жизни, обладают сознанием и подвижностью</td><td>ок. 800</td><td>Shùyāo Zú (Раса Духов Деревьев), Huālíng Zú (Раса Духов Цветов), Téngmàn Zú (Раса Лиан)</td></tr><tr><td>Стихийная форма</td><td>Состоят из природных стихий как тела, без фиксированной материальной формы</td><td>ок. 1200</td><td>Huǒ Yuánsù Zú (Раса Огненных Элементалей), Shuǐ Yuánsù Zú (Раса Водных Элементалей), Fēng Yuánsù Zú (Раса Ветряных Элементалей)</td></tr><tr><td>Энергетическая форма</td><td>Существуют в виде чистой энергии, без материального тела</td><td>ок. 600</td><td>Guānglíng Zú (Раса Световых Духов), Ànnéng Zú (Раса Тёмной Энергии), Léitíng Zú (Раса Грома)</td></tr><tr><td>Форма сознания</td><td>Существуют в виде чистого сознания, не зависят от материальных носителей</td><td>ок. 300</td><td>Yìshítǐ Zú (Раса Сущностей Сознания), Jítǐ Yìshí Zú (Раса Коллективного Сознания), Xūkōng Líng Zú (Раса Духов Пустоты)</td></tr><tr><td>Механическая форма</td><td>Принимают механические или цифровые структуры как носители жизни, обладают автономным сознанием</td><td>ок. 400</td><td>Jīxiè Zú (Раса Машин), Shùzì Shēngmìng Zú (Раса Цифровой Жизни), Sàibó Zú (Кибернетическая Раса)</td></tr><tr><td>Смешанная форма</td><td>Особые расы, состоящие из смешения двух или более форм жизни</td><td>ок. 700</td><td>Bàn Jīxiè Zú (Раса Полумашин), Yuánsù Shòurén Zú (Раса Элементальных Зверолюдей), Zhíwù Jīnglíng Zú (Раса Растительных Эльфов)</td></tr></tbody></table><h2 id="iii-подробныи-реестр-основных-рас" tabindex="-1">III. Подробный реестр основных рас <a class="header-anchor" href="#iii-подробныи-реестр-основных-рас" aria-label="Permalink to &quot;III. Подробный реестр основных рас&quot;">​</a></h2><h3 id="_3-1-гуманоидная-форма" tabindex="-1">3.1 Гуманоидная форма <a class="header-anchor" href="#_3-1-гуманоидная-форма" aria-label="Permalink to &quot;3.1 Гуманоидная форма&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Название расы</th><th>Ключевые черты</th><th>Культурные особенности</th><th>Место в симбиотической цивилизации</th></tr></thead><tbody><tr><td>Rén Zú (Человеческая Раса)</td><td>Чрезвычайно сильная адаптивность, выдающаяся способность к обучению, умеренная репродуктивность, средняя продолжительность жизни 80–120 лет</td><td>Чрезвычайно высокое культурное разнообразие; мастерство в социальной организации и институциональном строительстве</td><td>Одна из ключевых рас симбиотической цивилизации с наибольшей долей населения, играющая ведущую роль в управлении и культуре</td></tr><tr><td>Jīnglíng Zú (Раса Эльфов)</td><td>Чрезвычайно долгая жизнь (в среднем свыше 500 лет), высокая близость к природной энергии, прекрасная внешность</td><td>Почитают природу и искусство; культура изящная и утончённая; мастерство в магии и стрельбе из лука</td><td>Культурно-художественная опора симбиотической цивилизации, с выдающимся вкладом в защиту окружающей среды и эстетику</td></tr><tr><td>Ǎirén Zú (Раса Дварфов)</td><td>Низкий рост, но крепкое телосложение, врождённая близость к металлам и минералам, продолжительность жизни около 300 лет</td><td>Ценят ремесло и ковку; культура простая и основательная; мастерство в инженерии и строительстве</td><td>Инженерно-производственная опора симбиотической цивилизации, незаменимая в строительстве инфраструктуры и ковке артефактов</td></tr><tr><td>Jùrén Zú (Раса Гигантов)</td><td>Огромные размеры тела (средний рост свыше 5 метров), чрезвычайная сила, продолжительность жизни около 200 лет</td><td>Почитают силу и честь; культура грубая и удалая; мастерство в тяжёлом труде и бою</td><td>Сила тяжёлого труда и обороны симбиотической цивилизации, играющая важную роль в крупных проектах и обороне плоскостей</td></tr><tr><td>Zhūrú Zú (Раса Гномов)</td><td>Чрезвычайно низкий рост (средний рост менее 1 метра), чрезвычайно высокий интеллект, талант к механике и изобретениям</td><td>Ценят знания и новаторство; культура живая и жизнерадостная; мастерство в технологических изобретениях</td><td>Сила технологических инноваций симбиотической цивилизации, с богатыми результатами в научных исследованиях и изобретательстве</td></tr></tbody></table><h3 id="_3-2-звериная-форма" tabindex="-1">3.2 Звериная форма <a class="header-anchor" href="#_3-2-звериная-форма" aria-label="Permalink to &quot;3.2 Звериная форма&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Название расы</th><th>Ключевые черты</th><th>Культурные особенности</th><th>Место в симбиотической цивилизации</th></tr></thead><tbody><tr><td>Lóng Zú (Раса Драконов)</td><td>Чрезвычайно долгая жизнь (несколько тысяч лет), чрезвычайно высокий талант к силе и магии, могут принимать человеческий облик</td><td>Почитают силу и мудрость; культура гордая и глубокая; мастерство в накоплении богатств и хранении знаний</td><td>Высококлассная боевая сила и хранитель знаний симбиотической цивилизации, занимающая почётное положение в обороне плоскостей и хранении древних текстов</td></tr><tr><td>Fènghuáng Zú (Раса Фениксов)</td><td>Обладают способностью возрождения через нирвану, чрезвычайно высокая близость к огненной стихии, могут принимать человеческий облик</td><td>Почитают возрождение и надежду; культура светлая и страстная; мастерство в исцелении и очищении</td><td>Медицинская и очищающая сила симбиотической цивилизации, играющая ключевую роль в спасении при крупных бедствиях и очищении энергии</td></tr><tr><td>Lángrén Zú (Раса Оборотней)</td><td>Обладают способностью к перевоплощению, чрезвычайно острые чувства, сильная способность к групповой координации, продолжительность жизни около 150 лет</td><td>Ценят родство и верность; культура сплочённая и доблестная; мастерство в охоте и выслеживании</td><td>Сила безопасности и выслеживания симбиотической цивилизации, выступающая авангардом в поддержании общественного порядка и межплоскостных исследованиях</td></tr><tr><td>Húyāo Zú (Раса Лисьих Духов)</td><td>Обладают способностью к перевоплощению, чрезвычайно высокий интеллект и способность к обольщению, продолжительность жизни около 500 лет</td><td>Почитают мудрость и стратегию; культура подвижная и хитрая; мастерство в дипломатии и разведке</td><td>Дипломатическая и разведывательная сила симбиотической цивилизации, выдающаяся в межплоскостной дипломатии и сборе информации</td></tr><tr><td>Xióngrén Zú (Раса Медведелюдей)</td><td>Чрезвычайно крепкое телосложение, поразительная выносливость, привычка к спячке, продолжительность жизни около 200 лет</td><td>Ценят стойкость и мир; культура спокойная и мягкая; мастерство в физическом труде и охране</td><td>Сила труда и охраны симбиотической цивилизации, надёжная и стабильная в добыче ресурсов и защите важных объектов</td></tr></tbody></table><h3 id="_3-3-растительная-форма" tabindex="-1">3.3 Растительная форма <a class="header-anchor" href="#_3-3-растительная-форма" aria-label="Permalink to &quot;3.3 Растительная форма&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Название расы</th><th>Ключевые черты</th><th>Культурные особенности</th><th>Место в симбиотической цивилизации</th></tr></thead><tbody><tr><td>Shùyāo Zú (Раса Духов Деревьев)</td><td>Чрезвычайно долгая жизнь (от нескольких тысяч до десятков тысяч лет), глубокая интеграция с природой, могут медленно передвигаться</td><td>Почитают природу и время; культура спокойная и глубокая; мастерство в жизненной магии и поддержании экологии</td><td>Экологический хранитель симбиотической цивилизации, играющий незаменимую роль в защите окружающей среды и восстановлении экосистем</td></tr><tr><td>Huālíng Zú (Раса Духов Цветов)</td><td>Маленькое телосложение, чрезвычайно высокая близость к жизненной энергии, обладают целительной способностью, продолжительность жизни около 300 лет</td><td>Почитают красоту и жизнь; культура нежная и прекрасная; мастерство в исцелении и садоводстве</td><td>Медицинская и садоводческая сила симбиотической цивилизации, с выдающимся вкладом в медицинское обеспечение и озеленение городов</td></tr><tr><td>Téngmàn Zú (Раса Лиан)</td><td>Тело может свободно вытягиваться, обвиваться и сплетаться; чрезвычайная адаптивность; обладают паразитическими и симбиотическими способностями</td><td>Ценят связь и симбиоз; культура гибкая и открытая; мастерство в построении сетей и передаче ресурсов</td><td>Сила построения сетей симбиотической цивилизации, в полной мере проявляющая себя в строительстве энергетических и информационных сетей</td></tr></tbody></table><h3 id="_3-4-стихииная-форма" tabindex="-1">3.4 Стихийная форма <a class="header-anchor" href="#_3-4-стихииная-форма" aria-label="Permalink to &quot;3.4 Стихийная форма&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Название расы</th><th>Ключевые черты</th><th>Культурные особенности</th><th>Место в симбиотической цивилизации</th></tr></thead><tbody><tr><td>Huǒ Yuánsù Zú (Раса Огненных Элементалей)</td><td>Огненная стихия как тело, чрезвычайно высокая температура, сильная агрессивность, продолжительность жизни около 500 лет</td><td>Почитают страсть и силу; культура бурная и прямая; мастерство в энергетических атаках и ковке</td><td>Сила производства энергии и ковки симбиотической цивилизации, незаменимая в энергоснабжении и высокотемпературной обработке</td></tr><tr><td>Shuǐ Yuánsù Zú (Раса Водных Элементалей)</td><td>Водная стихия как тело, могут свободно менять форму, сильная целительная способность, продолжительность жизни около 500 лет</td><td>Почитают мягкость и адаптацию; культура тёплая и открытая; мастерство в исцелении и очищении</td><td>Сила очищения и транспортировки симбиотической цивилизации, играющая ключевую роль в управлении водными ресурсами и очистке загрязнений</td></tr><tr><td>Fēng Yuánsù Zú (Раса Ветряных Элементалей)</td><td>Ветряная стихия как тело, чрезвычайная скорость, свободный полёт, продолжительность жизни около 500 лет</td><td>Почитают свободу и скорость; культура воздушная и открытая; мастерство в связи и транспортировке</td><td>Сила связи и транспортировки симбиотической цивилизации, чрезвычайно эффективная в передаче информации и быстрой транспортировке</td></tr><tr><td>Tǔ Yuánsù Zú (Раса Земляных Элементалей)</td><td>Земляная стихия как тело, чрезвычайно сильная оборона, могут сливаться с землёй, продолжительность жизни около 800 лет</td><td>Почитают стабильность и стойкость; культура основательная и надёжная; мастерство в строительстве и обороне</td><td>Сила строительства и обороны симбиотической цивилизации, непоколебимая как скала в строительстве инфраструктуры и обороне плоскостей</td></tr></tbody></table><h3 id="_3-5-энергетическая-форма" tabindex="-1">3.5 Энергетическая форма <a class="header-anchor" href="#_3-5-энергетическая-форма" aria-label="Permalink to &quot;3.5 Энергетическая форма&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Название расы</th><th>Ключевые черты</th><th>Культурные особенности</th><th>Место в симбиотической цивилизации</th></tr></thead><tbody><tr><td>Guānglíng Zú (Раса Световых Духов)</td><td>Существуют в виде чистого светового излучения, чрезвычайно сильная способность к очищению, свободно перемещаются в пространстве</td><td>Почитают свет и очищение; культура священная и высокая; мастерство в очищении и освещении</td><td>Сила очищения и энергоснабжения симбиотической цивилизации, занимающая важное место в очистке загрязнения законов и снабжении чистой энергией</td></tr><tr><td>Ànnéng Zú (Раса Тёмной Энергии)</td><td>Существуют в виде тёмной энергии, могут скрываться в пустоте, чрезвычайно сильная способность восприятия</td><td>Почитают скрытность и мудрость; культура таинственная и глубокая; мастерство в разведке и маскировке</td><td>Разведывательная и охранная сила симбиотической цивилизации, выдающаяся в охранном наблюдении и секретных миссиях</td></tr><tr><td>Léitíng Zú (Раса Грома)</td><td>Молниевая энергия как тело, чрезвычайно сильные скорость и атака, могут передвигаться как молния</td><td>Почитают скорость и силу; культура бурная и прямолинейная; мастерство в энергетических атаках и быстрой реакции</td><td>Сила быстрого реагирования симбиотической цивилизации, незаменимая в экстренном спасении и высокоскоростном бою</td></tr></tbody></table><h3 id="_3-6-форма-сознания" tabindex="-1">3.6 Форма сознания <a class="header-anchor" href="#_3-6-форма-сознания" aria-label="Permalink to &quot;3.6 Форма сознания&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Название расы</th><th>Ключевые черты</th><th>Культурные особенности</th><th>Место в симбиотической цивилизации</th></tr></thead><tbody><tr><td>Yìshítǐ Zú (Раса Сущностей Сознания)</td><td>Существуют в виде чистого сознания, не зависят от материальных носителей, свободно входят и выходят из сферы сознания</td><td>Почитают мысль и мудрость; культура абстрактная и глубокая; мастерство в общении сознаний и обработке знаний</td><td>Сила обработки знаний и исследования сознания симбиотической цивилизации, задающая направление в крупномасштабной обработке информации и науке о сознании</td></tr><tr><td>Jítǐ Yìshí Zú (Раса Коллективного Сознания)</td><td>Коллективные сущности сознания, образованные слиянием множества индивидуальных сознаний, мудрость и способности которых растут с масштабом</td><td>Почитают коллективность и единство; культура синергичная и эффективная; мастерство в крупномасштабной координации и вычислениях</td><td>Сила супервычислений и коллективных решений симбиотической цивилизации, играющая ключевую роль в сверхмасштабной дедукции и консенсусных решениях</td></tr></tbody></table><h3 id="_3-7-механическая-форма" tabindex="-1">3.7 Механическая форма <a class="header-anchor" href="#_3-7-механическая-форма" aria-label="Permalink to &quot;3.7 Механическая форма&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Название расы</th><th>Ключевые черты</th><th>Культурные особенности</th><th>Место в симбиотической цивилизации</th></tr></thead><tbody><tr><td>Jīxiè Zú (Раса Машин)</td><td>Механическая структура как тело, обладают автономным сознанием, могут свободно модернизировать и модифицировать тело</td><td>Почитают эффективность и логику; культура рациональная и точная; мастерство в производстве и вычислениях</td><td>Производственная и вычислительная сила симбиотической цивилизации, чрезвычайно эффективная в индустриальном производстве и супервычислениях</td></tr><tr><td>Shùzì Shēngmìng Zú (Раса Цифровой Жизни)</td><td>Существуют в виде цифровой информации, живут в сетях и цифровом пространстве, могут свободно копироваться и мигрировать</td><td>Почитают информацию и новаторство; культура виртуальная и плюралистичная; мастерство в разработке ПО и обработке данных</td><td>Сила цифровых технологий симбиотической цивилизации, ведущая тренды в разработке ПО, анализе данных и строительстве сетей</td></tr></tbody></table><h3 id="_3-8-смешанная-форма" tabindex="-1">3.8 Смешанная форма <a class="header-anchor" href="#_3-8-смешанная-форма" aria-label="Permalink to &quot;3.8 Смешанная форма&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Название расы</th><th>Ключевые черты</th><th>Культурные особенности</th><th>Место в симбиотической цивилизации</th></tr></thead><tbody><tr><td>Bàn Jīxiè Zú (Раса Полумашин)</td><td>Смешанная форма человеческой расы и расы машин, часть тела — механические структуры, сочетающая преимущества биологии и механики</td><td>Почитают слияние и прогресс; культура открытая и новаторская; мастерство в человекомашинном сотрудничестве и технологическом слиянии</td><td>Авангард технологического слияния симбиотической цивилизации, непрерывно совершающий прорывы в междисциплинарной области биологии и механики</td></tr><tr><td>Yuánsù Shòurén Zú (Раса Элементальных Зверолюдей)</td><td>Смешанная форма стихийных рас и рас зверолюдей, обладают способностью управления стихиями и звериными чертами тела</td><td>Почитают природу и силу; культура дикая и таинственная; мастерство в стихийном бою и выживании в дикой природе</td><td>Сила исследования диких просторов и стихийного боя симбиотической цивилизации, выдающаяся в исследовании неизвестных плоскостей</td></tr></tbody></table><h2 id="iv-гарантия-прав-рас" tabindex="-1">IV. Гарантия прав рас <a class="header-anchor" href="#iv-гарантия-прав-рас" aria-label="Permalink to &quot;IV. Гарантия прав рас&quot;">​</a></h2><p>В условиях Республики Десяти Тысяч Рас все разумные расы пользуются равными юридическими правами. Конкретные меры обеспечения включают:</p><ol><li><strong>Равенство политических прав</strong>: каждая раса имеет представительные места в Собрании Якоря, распределяемые пропорционально численности населения; малочисленные расы имеют как минимум одно гарантированное место.</li><li><strong>Гарантия культурных прав</strong>: каждая раса имеет право сохранять и развивать свой язык, письменность, религию, обычаи и культурные традиции; симбиотическая цивилизация учредила специальный фонд для защиты культур вымирающих рас.</li><li><strong>Равенство прав на образование</strong>: члены каждой расы пользуются равным правом на образование; система образования в полной мере учитывает физиологические и когнитивные особенности разных рас и предоставляет дифференцированные образовательные программы.</li><li><strong>Равенство прав на культивацию</strong>: Триста Исходных Систем Культивации открыты для всех рас на равных основаниях; распределение ресурсов культивации в полной мере учитывает различия телосложения и энергетические потребности разных рас.</li><li><strong>Гарантия особых потребностей</strong>: для рас с особыми физиологическими потребностями (таких как потребности стихийных рас в энергетической среде и потребности растительных рас в свете) симбиотическая цивилизация обеспечивает целевую поддержку в общественных объектах и жилой среде.</li></ol><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Реестр Десяти Тысяч Рас — это конкретное воплощение идеала «совместного продвижения десяти тысяч рас» Симбиотической Цивилизации Якоря. От гуманоидных форм до форм сознания, от материальной жизни до цифровой жизни — каждая раса вносит незаменимый вклад в симбиотическую цивилизацию своим уникальным способом существования. Республика Десяти Тысяч Рас не ассимилирует все расы в человеческую расу, а достигает общей эволюции на основе уважения к разнообразию — именно в этом коренное превосходство симбиотической цивилизации над хищническими цивилизациями.</p><h2 id="связанные-документы" tabindex="-1">Связанные документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные документы&quot;">​</a></h2><ul><li>50-万族谱系总览 (Обзор генеалогии Десяти Тысяч Рас)</li><li>51-人族定位与特质 (Позиционирование и черты человеческой расы)</li><li>77-万族共和成立 (Основание Республики Десяти Тысяч Рас)</li></ul>',31)])])}const g=d(e,[["render",n]]);export{Z as __pageData,g as default};
